-- ---------------------------------------------------------------------------
-- F) 13565 "Twice Removed" -- Withered Ent (HavenCore + nelt).
--    Petrified Root (45911, use-spell set in B) casts 64306 on a dead Darkscale
--    Scout; the Ent it summons credits its summoner and follows them.
--    The template is imported the same way 190_ imported its 31 (cata_world,
--    +3,700,000 band) and lifted to the scouts' level band. REPLACE INTO
--    rather than DELETE + INSERT: the SQL codestyle forbids DELETE on
--    creature_template, and REPLACE keeps the file re-runnable.
-- ---------------------------------------------------------------------------
REPLACE INTO `creature_template` (`entry`, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`, `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, `lootid`, `pickpocketloot`, `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `DamageModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `flags_extra`, `ScriptName`, `VerifiedBuild`)
SELECT `entry` + 3700000, 0, 0, 0, 0, 0, `name`, `subname`, `IconName`, `gossip_menu_id`, 80, 81, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, 0, 0, 0, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, 'SmartAI', 0, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `DamageModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `flags_extra`, '', `VerifiedBuild`
FROM `cata_world`.`creature_template`
WHERE `entry` = 34009;

